-- ----------------------------
-- Table structure for npc_spawner_spawn_effects
-- ----------------------------
DROP TABLE IF EXISTS "npc_spawner_spawn_effects";
CREATE TABLE "npc_spawner_spawn_effects" (
  "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
  "spawner_id" integer DEFAULT 0,
  "life_time" float NOT NULL DEFAULT 0.0,
  "despawn_on_creator_death" boolean NOT NULL DEFAULT 't',
  "use_summoner_aggro_target" boolean NOT NULL DEFAULT 't',
  "activation_state" boolean NOT NULL DEFAULT 'f',
  "use_summoner_faction" boolean NOT NULL DEFAULT 'f'
);

